"""Retired pet-panel contract; retained for source review, not collected."""
HISTORICAL_CONTRACTS = '# ruff: noqa: E402\n"""Historical manual assertions adapted to the account-free offline runner."""\nimport unittest\nfrom module.config import server as _test_server\n_test_server.set_lang("global_cn")\n\nfrom tasks.dungeon.stamina_status import CombatStaminaStatusMixin, PET_REPEAT_RESOURCE_LAYOUT\n\nclass FakeDevice:\n    image = object()\n\n    def screenshot(self):\n        return self.image\n\nclass SnapshotProbe(CombatStaminaStatusMixin):\n    COMBAT_PREPARE_TIMEOUT_SECONDS = 1\n    RESOURCE_BAR_TIMEOUT_SECONDS = 1\n    RESOURCE_BAR_TIMEOUT_COUNT = 10\n\n    def __init__(self):\n        self.device = FakeDevice()\n        self.stage = "prepare"\n        self.events = []\n        self.parsed = {\n            key: SimpleNamespace(value=index + 1)\n            for index, key in enumerate(PET_REPEAT_RESOURCE_LAYOUT)\n        }\n\n    def _is_prepare_page(self):\n        return self.stage == "prepare"\n\n    def _ensure_fast_combat_state(self, enabled):\n        self.events.append(("fast_combat", enabled))\n        return not enabled\n\n    def appear(self, button):\n        return self.stage == "panel"\n\n    def appear_then_click(self, button, interval=0):\n        if self.stage == "prepare":\n            self.events.append("open")\n            self.stage = "panel"\n            return True\n        if self.stage == "panel":\n            self.events.append("close")\n            self.stage = "prepare"\n            return True\n        return False\n\n    def _ocr_pet_repeat_resources(self):\n        self.events.append("inspect")\n        return SimpleNamespace(values=self.parsed, icon_matches=[])\n\n    def _handle_repeat_count_overlay_additional(self):\n        return False\n\nclass FailedSnapshotProbe(SnapshotProbe):\n    RESOURCE_BAR_TIMEOUT_SECONDS = 0\n    RESOURCE_BAR_TIMEOUT_COUNT = 0\n\n    def _ocr_pet_repeat_resources(self):\n        self.events.append("inspect")\n        return SimpleNamespace(values=None, icon_matches=["stamina=miss"])\n\nfrom types import SimpleNamespace\n\n\n\nclass ManualChecks(unittest.TestCase):\n    def test_snapshot_success(self):\n        probe = SnapshotProbe()\n        parsed = probe._update_prepare_resource_snapshot()\n        expected_events = [("fast_combat", False), "open", "inspect", "close"]\n        if parsed is not probe.parsed or probe.events != expected_events:\n                    raise AssertionError(f"unexpected snapshot flow: parsed={parsed}, events={probe.events}")\n\n    def test_failed_snapshot_closes_panel(self):\n        failed_probe = FailedSnapshotProbe()\n        parsed = failed_probe._update_prepare_resource_snapshot()\n        if parsed is not None or failed_probe.stage != "prepare" or failed_probe.events[-1] != "close":\n                    raise AssertionError(\n                        f"failed snapshot did not close cleanly: parsed={parsed}, "\n                        f"stage={failed_probe.stage}, events={failed_probe.events}"\n                    )\n\n'
